const { withAppBuildGradle } = require("@expo/config-plugins");

/**
 * Keep native Android projects generated by Expo while allowing CI to use a
 * stable release key. Secrets are read by Gradle at build time and are never
 * written to the repository or to app config.
 */
module.exports = function withAndroidReleaseSigning(config) {
  return withAppBuildGradle(config, (mod) => {
    let contents = mod.modResults.contents;

    if (!contents.includes("pulseReleaseSigning")) {
      const releaseSigningConfig = `
        pulseReleaseSigning {
            def releaseKeystorePath = System.getenv("ANDROID_KEYSTORE_PATH")
            def releaseKeystorePassword = System.getenv("ANDROID_KEYSTORE_PASSWORD")
            def releaseKeyAlias = System.getenv("ANDROID_KEY_ALIAS")
            def releaseKeyPassword = System.getenv("ANDROID_KEY_PASSWORD")
            if (releaseKeystorePath != null && releaseKeystorePassword != null && releaseKeyAlias != null && releaseKeyPassword != null) {
                storeFile file(releaseKeystorePath)
                storePassword releaseKeystorePassword
                keyAlias releaseKeyAlias
                keyPassword releaseKeyPassword
            }
        }
`;

      contents = contents.replace(
        "    signingConfigs {",
        `    signingConfigs {${releaseSigningConfig}`,
      );
      contents = contents.replace(
        "            signingConfig signingConfigs.debug\n            def enableShrinkResources",
        '            signingConfig (System.getenv("ANDROID_KEYSTORE_PATH") != null ? signingConfigs.pulseReleaseSigning : signingConfigs.debug)\n            def enableShrinkResources',
      );
    }

    if (!contents.includes("pulseVersionCode")) {
      contents = contents.replace(
        "android {",
        'android {\n    def pulseVersionCode = (System.getenv("ANDROID_VERSION_CODE") ?: "1").toInteger()',
      );
      contents = contents.replace(/        versionCode \d+\n/, "        versionCode pulseVersionCode\n");
    }

    mod.modResults.contents = contents;
    return mod;
  });
};
